      code: "import { InteractionCollector, ActionRowBuilder, ButtonBuilder } from '@jubbio/core';\n\n// Butonlu mesaj gönder\nconst row = new ActionRowBuilder().addComponents(\n  new ButtonBuilder()\n    .setCustomId('confirm')\n    .setLabel('Onayla')\n    .setStyle(3),\n  new ButtonBuilder()\n    .setCustomId('cancel')\n    .setLabel('İptal')\n    .setStyle(4)\n);\n\nconst message = await rest.createMessage(channelId, {\n  content: 'Emin misin?',\n  components: [row]\n});\n\n// Etkileşim topla\nconst collector = new InteractionCollector(client, {\n  filter: (i) => i.user.id === userId,\n  messageId: message.id,\n  componentType: 2,\n  max: 1,\n  time: 30000\n});\n\ncollector.on('collect', async (interaction) => {\n  if (interaction.customId === 'confirm') {\n    await interaction.update({ content: 'Onaylandı!', components: [] });\n  } else {\n    await interaction.update({ content: 'İptal edildi.', components: [] });\n  }\n});\n\ncollector.on('end', (collected, reason) => {\n  if (reason === 'time') {\n    rest.editMessage(channelId, message.id, {\n      content: 'Süre doldu.',\n      components: []\n    });\n  }\n});"
